  function restaurantOrderValue(o){const value=Number(o&&o.pricing&&o.pricing.subtotal||0);return Number.isFinite(value)?Math.max(0,value):0}
  function restaurantPayableValue(o){const bps=Number(state.restaurant&&state.restaurant.commissionBps);if(!Number.isFinite(bps)||bps<0||bps>5000)return null;const subtotal=Number(o&&o.pricing&&o.pricing.subtotal||0),discount=Number(o&&o.pricing&&o.pricing.discount||0),menuConsideration=Math.max(0,(Number.isFinite(subtotal)?subtotal:0)-(Number.isFinite(discount)?discount:0));return Math.round(menuConsideration*(10000-bps)/100)/100}
  function restaurantDisplayValue(o){const net=restaurantPayableValue(o);return net==null?restaurantOrderValue(o):net}
  function commissionKnown(){return restaurantPayableValue({pricing:{subtotal:100,discount:0}})!=null}
