  function restaurantBreakdown(o){const netKnown=commissionKnown(),gross=restaurantOrderValue(o),payable=restaurantDisplayValue(o),commissionAmount=netKnown?Math.max(0,Math.round((gross-payable)*100)/100):0,bps=netKnown?Number(state.restaurant&&state.restaurant.commissionBps):0,pct=netKnown?(bps/100).toFixed(2).replace(/\.00$/,""):"";return'<div class="stack"><div class="settings-row"><span>Menu item subtotal snapshot</span><strong>'+money(gross)+'</strong></div>'+(netKnown?'<div class="settings-row"><span>Commission ('+h(pct)+'%)</span><strong>-'+money(commissionAmount)+'</strong></div>':'')+'<div class="divider"></div><div class="settings-row"><span><strong>'+h(restaurantValueLabel(o))+(netKnown?' (after commission)':'')+'</strong></span><strong>'+money(payable)+'</strong></div><p class="caption">'+(netKnown?'Commission already deducted using this restaurant\'s rate. Adjustments, refunds, COD and settlement are still not calculated on this screen; authoritative finance records come from the platform ledger.':'Order-value projection only. Commission, adjustments, refunds, COD and settlement are not calculated on this screen; authoritative finance records come from the platform ledger.')+'</p></div>'}
  function awaitingVerifiedPayment(o){return o&&o.paymentMethod!=="cod"&&o.paymentState!=="paid"&&o.paymentState!=="refunded"}
  function paymentPendingNotice(o){return awaitingVerifiedPayment(o)?'<div class="notice warning">'+icon("warning","small")+'<span>Customer online payment is still '+h(o.paymentState||"pending")+'. The restaurant cannot accept or prepare this order until payment is verified.</span></div>':""}
  function localDateKey(value){const d=value?new Date(Number(value)):new Date(),y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,"0"),day=String(d.getDate()).padStart(2,"0");return y+"-"+m+"-"+day}
