  function orderRow(o){return'<article class="card entity-row"><div class="avatar">'+h(String(o.restaurant||"O")[0])+'</div><div class="grow"><div class="cluster wrap"><h3 class="card-title">Order '+h(o.id)+'</h3><span class="status '+(o.status==="Order placed"?'warning':o.status==="Delivered"?'success':'')+'">'+h(o.status||"Order placed")+'</span></div><p class="supporting">'+h((o.items||[]).map(i=>(i.quantity||1)+'× '+i.name).slice(0,3).join(" · "))+'</p><p class="caption">'+money(o.total||o.pricing&&o.pricing.total||0)+(awaitingVerifiedPayment(o)?' · awaiting online payment':'')+'</p></div><button class="icon-button flat" data-action="open-order" data-order-id="'+h(o.id)+'">'+icon("chevron")+'</button></article>'}
